17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.LocalDate;
20	import java.util.Collection;
21	import java.util.List;
22	
23	import org.springframework.http.HttpHeaders;
24	import org.springframework.http.HttpStatus;
25	import org.springframework.http.ResponseEntity;
26	import org.springframework.samples.petclinic.mapper.OwnerMapper;
27	import org.springframework.samples.petclinic.mapper.PetMapper;
28	import org.springframework.samples.petclinic.mapper.VisitMapper;
29	import org.springframework.samples.petclinic.model.Owner;
30	import org.springframework.samples.petclinic.model.Pet;
31	import org.springframework.samples.petclinic.model.Visit;
32	import org.springframework.samples.petclinic.rest.api.OwnersApi;
33	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
34	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
35	import org.springframework.samples.petclinic.rest.dto.PetDto;
36	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
37	import org.springframework.samples.petclinic.rest.dto.VisitDto;
38	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
39	import org.springframework.samples.petclinic.service.ClinicService;
40	import org.springframework.security.access.prepost.PreAuthorize;
41	import org.springframework.web.bind.annotation.CrossOrigin;
42	import org.springframework.web.bind.annotation.RequestMapping;
43	import org.springframework.web.bind.annotation.RestController;
44	import org.springframework.web.util.UriComponentsBuilder;
45	
46	import jakarta.transaction.Transactional;
47	
48	/**
49	 * @author Vitaliy Fedoriv
50	 */
51	
52	@RestController
53	@CrossOrigin(exposedHeaders = "errors, content-type")
54	@RequestMapping("/api")
55	public class OwnerRestControllerV1 implements OwnersApi {
56	
57	    private final ClinicService clinicService;
58	
59	    private final OwnerMapper ownerMapper;
60	
61	    private final PetMapper petMapper;
62	
63	    private final VisitMapper visitMapper;
64	
65	    public OwnerRestControllerV1(ClinicService clinicService,
66	                                 OwnerMapper ownerMapper,
67	                                 PetMapper petMapper,
68	                                 VisitMapper visitMapper) {
69	        this.clinicService = clinicService;
70	        this.ownerMapper = ownerMapper;
71	        this.petMapper = petMapper;
72	        this.visitMapper = visitMapper;
73	    }
74	
75	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
76	    @Override
77	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
78	        Collection<Owner> owners;
79	        if (lastName != null) {
80	            owners = this.clinicService.findOwnerByLastName(lastName);
81	        } else {
82	            owners = this.clinicService.findAllOwners();
83	        }
84	        if (owners.isEmpty()) {
85	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
86	        }
87	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
88	    }
89	
90	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
91	    @Override
92	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
93	        Owner owner = this.clinicService.findOwnerById(ownerId);
94	        if (owner == null) {
95	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
96	        }
97	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
98	    }
99	
100	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
101	    @Override
102	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
103	        HttpHeaders headers = new HttpHeaders();
104	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
105	        String telephone = toE164(owner.getTelephone());
106	        if (telephone == null) {
107	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
108	        }
109	        owner.setTelephone(telephone);
110	        if (owner.getEmail() != null) {
111	            owner.setEmail(owner.getEmail().toLowerCase());
112	        }
113	        if (owner.getRegistrationDate() == null) {
114	            owner.setRegistrationDate(LocalDate.now());
115	        }
116	        if (!this.clinicService.findOwnerByTelephone(telephone).isEmpty()) {
117	            return new ResponseEntity<>(HttpStatus.CONFLICT);
118	        }
119	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold()) && isHouseholdDuplicate(owner)) {
120	            return new ResponseEntity<>(HttpStatus.CONFLICT);
121	        }
122	        owner.setCustomerCode(nextCustomerCode(owner.getLastName()));
123	        this.clinicService.saveOwner(owner);
124	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
125	        headers.setLocation(UriComponentsBuilder.newInstance()
126	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
127	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
128	    }
129	
130	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
131	    @Override
132	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
133	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
134	        if (currentOwner == null) {
135	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
136	        }
137	        currentOwner.setAddress(ownerFieldsDto.getAddress());
138	        currentOwner.setCity(ownerFieldsDto.getCity());
139	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
140	        currentOwner.setLastName(ownerFieldsDto.getLastName());
141	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
142	        String email = ownerFieldsDto.getEmail();
143	        currentOwner.setEmail(email == null ? null : email.toLowerCase());
144	        this.clinicService.saveOwner(currentOwner);
145	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
146	    }
147	
148	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
149	    @Transactional
150	    @Override
151	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
152	        Owner owner = this.clinicService.findOwnerById(ownerId);
153	        if (owner == null) {
154	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
155	        }
156	        this.clinicService.deleteOwner(owner);
157	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
158	    }
159	
160	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
161	    @Override
162	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
163	        Owner owner = this.clinicService.findOwnerById(ownerId);
164	        if (owner == null) {
165	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
166	        }
167	        HttpHeaders headers = new HttpHeaders();
168	        Pet pet = petMapper.toPet(petFieldsDto);
169	        owner.setId(ownerId);
170	        pet.setOwner(owner);
171	        pet.getType().setName(null);
172	        this.clinicService.savePet(pet);
173	        PetDto petDto = petMapper.toPetDto(pet);
174	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
175	            .buildAndExpand(pet.getId()).toUri());
176	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
177	    }
178	
179	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
180	    @Override
181	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
182	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
183	        if (currentOwner != null) {
184	            Pet currentPet = this.clinicService.findPetById(petId);
185	            if (currentPet != null) {
186	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
187	                currentPet.setName(petFieldsDto.getName());
188	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
189	                this.clinicService.savePet(currentPet);
190	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
191	            }
192	        }
193	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
194	    }
195	
196	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
197	    @Override
198	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
199	        HttpHeaders headers = new HttpHeaders();
200	        Visit visit = visitMapper.toVisit(visitFieldsDto);
201	        Pet pet = new Pet();
202	        pet.setId(petId);
203	        visit.setPet(pet);
204	        this.clinicService.saveVisit(visit);
205	        VisitDto visitDto = visitMapper.toVisitDto(visit);
206	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
207	            .buildAndExpand(visit.getId()).toUri());
208	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
209	    }
210	
211	
212	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
213	    @Override
214	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
215	        Owner owner = this.clinicService.findOwnerById(ownerId);
216	        if (owner != null) {
217	            Pet pet = owner.getPet(petId);
218	            if (pet != null) {
219	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
220	            }
221	        }
222	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
223	    }
224	
225	    /**
226	     * Whether an existing owner already shares the same last name and address as the
227	     * given owner. Both fields are compared case-insensitively with runs of whitespace
228	     * collapsed to a single space (and surrounding whitespace trimmed).
229	     *
230	     * @param owner the candidate owner being created
231	     * @return {@code true} if a matching owner already exists
232	     */
233	    private boolean isHouseholdDuplicate(Owner owner) {
234	        String lastName = normalize(owner.getLastName());
235	        String address = normalize(owner.getAddress());
236	        return this.clinicService.findAllOwners().stream()
237	            .anyMatch(existing -> normalize(existing.getLastName()).equals(lastName)
238	                && normalize(existing.getAddress()).equals(address));
239	    }
240	
241	    /**
242	     * Normalise a value for case-insensitive, whitespace-insensitive comparison:
243	     * trim, collapse internal runs of whitespace to a single space and lower-case.
244	     */
245	    private static String normalize(String value) {
246	        if (value == null) {
247	            return "";
248	        }
249	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
250	    }
251	
252	    /**
253	     * Build the next customer code, formatted {@code <LAST3>-<NNNN>}: LAST3 is the
254	     * upper-cased first three letters of the given last name and NNNN is a global
255	     * 4-digit zero-padded sequence equal to one more than the current number of
256	     * owners (e.g. {@code SMI-0007}).
257	     *
258	     * @param lastName the owner's last name
259	     * @return the assigned customer code
260	     */
261	    private String nextCustomerCode(String lastName) {
262	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
263	        long sequence = this.clinicService.findAllOwners().size() + 1L;
264	        return String.format("%s-%04d", last3, sequence);
265	    }
266	
267	    /**
268	     * Normalise a telephone number to E.164 form: keep a leading '+' and country
269	     * code when present, otherwise assume country code '+61' and drop a single
270	     * leading '0' from the national digits. Spaces, dashes and brackets are
271	     * stripped. The result must contain 8 to 15 digits after the '+'.
272	     *
273	     * @return the E.164 string (e.g. "+61412345678"), or {@code null} if the
274	     *         input cannot form a valid E.164 number.
275	     */
276	    private static String toE164(String raw) {
277	        if (raw == null) {
278	            return null;
279	        }
280	        String cleaned = raw.replaceAll("[\\s()-]", "");
281	        String digits;
282	        if (cleaned.startsWith("+")) {
283	            digits = cleaned.substring(1);
284	        } else {
285	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
286	            digits = "61" + national;
287	        }
288	        if (!digits.matches("\\d{8,15}")) {
289	            return null;
290	        }
291	        return "+" + digits;
292	    }
293	}
