    /**
     * Whether an existing owner already shares the same last name and address as the
     * given owner. Both fields are compared case-insensitively with runs of whitespace
     * collapsed to a single space (and surrounding whitespace trimmed).
     *
     * @param owner the candidate owner being created
     * @return {@code true} if a matching owner already exists
     */
    private boolean isHouseholdDuplicate(Owner owner) {
        String lastName = normalize(owner.getLastName());
        String address = normalize(owner.getAddress());
        return this.clinicService.findAllOwners().stream()
            .anyMatch(existing -> normalize(existing.getLastName()).equals(lastName)
                && normalize(existing.getAddress()).equals(address));
    }

    /**
     * Normalise a value for case-insensitive, whitespace-insensitive comparison:
     * trim, collapse internal runs of whitespace to a single space and lower-case.
     */
    private static String normalize(String value) {
        if (value == null) {
            return "";
        }
        return value.trim().replaceAll("\\s+", " ").toLowerCase();
    }

    /**
     * Build the next customer code, formatted {@code <LAST3>-<NNNN>}: LAST3 is the
     * upper-cased first three letters of the given last name and NNNN is a global
     * 4-digit zero-padded sequence equal to one more than the current number of
     * owners (e.g. {@code SMI-0007}).
     *
     * @param lastName the owner's last name
     * @return the assigned customer code
     */
    private String nextCustomerCode(String lastName) {
        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
        long sequence = this.clinicService.findAllOwners().size() + 1L;
        return String.format("%s-%04d", last3, sequence);
    }

    /**
     * Normalise a telephone number to E.164 form: keep a leading '+' and country
     * code when present, otherwise assume country code '+61' and drop a single
     * leading '0' from the national digits. Spaces, dashes and brackets are
     * stripped. The result must contain 8 to 15 digits after the '+'.
     *
     * @return the E.164 string (e.g. "+61412345678"), or {@code null} if the
     *         input cannot form a valid E.164 number.
     */
    private static String toE164(String raw) {
        if (raw == null) {
            return null;
        }
        String cleaned = raw.replaceAll("[\\s()-]", "");
        String digits;
        if (cleaned.startsWith("+")) {
            digits = cleaned.substring(1);
        } else {
            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
            digits = "61" + national;
        }
        if (!digits.matches("\\d{8,15}")) {
            return null;
        }
        return "+" + digits;
    }
